const d = msg.payload;
const cooldown = 60000;
const now = Date.now();
let alerts = [];

const gemelo = global.get('gemelo');
const u = (gemelo && gemelo.umbrales) || {
    co2: { limite: 400 },
    sonido: { limite: 80 },
    distancia: { limite: 20 }
};

if (d.distancia < u.distancia.limite) {
    const last = context.get('d_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Distancia crítica!*\nObjeto a ' + Number(d.distancia).toFixed(1) + ' cm (límite: ' + u.distancia.limite + ' cm)');
        context.set('d_alert', now);
    }
}
if (d.co2 > u.co2.limite) {
    const last = context.get('g_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Nivel de CO2 elevado!*\nValor: ' + d.co2 + ' ppm (límite: ' + u.co2.limite + ' ppm)');
        context.set('g_alert', now);
    }
}
if (d.sonido > u.sonido.limite) {
    const last = context.get('s_alert') || 0;
    if (now - last > cooldown) {
        alerts.push('⚠️ *Ruido excesivo!*\n' + d.sonido + '% (límite: ' + u.sonido.limite + '%)');
        context.set('s_alert', now);
    }
}
if (alerts.length > 0) {
    msg.payload = {
        chatId: '1138232122',
        type: 'message',
        content: '🚨 *ALERTA ESTACIÓN IOT*\n\n' + alerts.join('\n\n')
    };
    return msg;
}
return null;

const chatId = msg.payload.chatId || '1138232122';
const cmd = String(msg.payload.content || '').trim().toUpperCase();

let accion = '';
if (cmd === 'ON' || cmd === '1')           accion = 'ON';
else if (cmd === 'OFF' || cmd === '0')    accion = 'OFF';
else if (cmd === 'TOGGLE' || cmd === 'T') accion = 'TOGGLE';
else {
    return [null, {
        payload: { chatId: chatId, type: 'message', content: '❌ Usá: /led ON, /led OFF o /led TOGGLE' }
    }];
}

return [
    { payload: accion },                                        // Output 1 → MQTT
    { payload: { chatId: chatId, type: 'message', content: '✅ LED ' + accion } }  // Output 2 → Telegram
];

const estado = String(msg.payload).toUpperCase();
const icono = estado === 'ON' ? '🟢' : '🔴';
msg.payload = {
    chatId: '1138232122',
    type: 'message',
    content: icono + ' LED ' + (estado === 'ON' ? 'ENCENDIDO' : 'APAGADO')
};
return msg;
